function validate([current, correct]) {
  const format = /^([01]\d|2[0-3]):[0-5]\d$/;
  if (typeof current !== 'string' || !format.test(current)) return 'current must be a time like "09:05".';
  if (typeof correct !== 'string' || !format.test(correct)) return 'correct must be a time like "09:05".';
  if (current > correct) return 'current must not be later than correct.';
  return null;
}

