function convertTime(current, correct) {
  const toMinutes = (time) => Number(time.slice(0, 2)) * 60 + Number(time.slice(3, 5));
  let remaining = toMinutes(correct) - toMinutes(current);
  let operations = 0;

  for (const step of [60, 15, 5, 1]) {
    operations += Math.floor(remaining / step);
    remaining %= step;
  }
  return operations;
}

