function convertTime(current, correct) {
  const [ch, cm] = current.split(':').map(Number);
  const [th, tm] = correct.split(':').map(Number);
  const gap = (th * 60 + tm) - (ch * 60 + cm);
  const best = new Array(gap + 1).fill(Infinity);
  best[0] = 0;
  for (let d = 1; d <= gap; d++)
    for (const step of [1, 5, 15, 60])
      if (step <= d) best[d] = Math.min(best[d], best[d - step] + 1);
  return best[gap];
}

