function generate(rand, size) {
  const show = (minutes) => String(Math.floor(minutes / 60)).padStart(2, '0') + ':' + String(minutes % 60).padStart(2, '0');
  const start = Math.floor(rand() * 1440);
  let gap;
  if (size === 'large') gap = Math.floor(rand() * (1440 - start));
  else {
    const pick = rand();
    gap = pick < 0.15 ? 0 : pick < 0.6 ? Math.floor(rand() * 80) : Math.floor(rand() * 400);
    gap = Math.min(gap, 1439 - start);
  }
  return [show(start), show(start + gap)];
}
